static const double memtune_xgb_v5_one_base_score = 1.6413599999999999;


static const double memtune_xgb_v5_imputation[MEMTUNE_XGB_V5_FEATURE_COUNT] = {
    1, 1, 0, 0, 5.4730919999999994, 245,
    276258.90999999997, 0, 0, 1102.703, 301.55500000000001, 2,
    0.38644057047693803, 12.529097404473836, 6.6390990616288761, 4.9279925425696121, 7.2412905687537652, 6,
    3, 260, 744, 2, 0.69314718055994529, 5.5373342670185366,
};

static double memtune_xgb_v5_tree(const double *features, const uint32_t *offsets,
    const int32_t *left, const int32_t *right, const int32_t *split_index,
    const double *split_condition, const uint8_t *default_left,
    const double *leaf_weight, uint32_t tree)
{
    int32_t node = 0;
    uint32_t base = offsets[tree];
    uint32_t end = offsets[tree + 1];
    while (node >= 0 && base + (uint32_t)node < end) {
        uint32_t index = base + (uint32_t)node;
        if (left[index] < 0 && right[index] < 0)
            return leaf_weight[index];
        int32_t feature = split_index[index];
        double value = (feature >= 0 && feature < MEMTUNE_XGB_V5_FEATURE_COUNT) ?
            features[feature] : NAN;
        if (!isfinite(value))
            node = default_left[index] ? left[index] : right[index];
        else
            node = value < split_condition[index] ? left[index] : right[index];
    }
    return NAN;
}

static double memtune_xgb_v5_predict_target(const double *features, double base_score,
    const uint32_t *offsets, const int32_t *left, const int32_t *right,
    const int32_t *split_index, const double *split_condition,
    const uint8_t *default_left, const double *leaf_weight)
{
    double result = base_score;
    uint32_t tree;
    for (tree = 0; tree < 240; ++tree)
        result += memtune_xgb_v5_tree(features, offsets, left, right, split_index,
            split_condition, default_left, leaf_weight, tree);
    return result;
}

static unsigned long long memtune_xgb_v5_hash_u64(unsigned long long hash,
    unsigned long long value)
{
    int index;
    for (index = 0; index < 8; ++index) {
        hash ^= (value >> (index * 8)) & 0xffU;
        hash *= MEMTUNE_FNV_PRIME;
    }
    return hash;
}

static int64_t memtune_xgb_v5_leaf_id(double cache_mb, double one_mb, double multi_mb)
{
    unsigned long long hash = MEMTUNE_FNV_OFFSET;
    unsigned long long bits;
    memcpy(&bits, &cache_mb, sizeof(bits)); hash = memtune_xgb_v5_hash_u64(hash, bits);
    memcpy(&bits, &one_mb, sizeof(bits)); hash = memtune_xgb_v5_hash_u64(hash, bits);
    memcpy(&bits, &multi_mb, sizeof(bits)); hash = memtune_xgb_v5_hash_u64(hash, bits);
    hash &= 0x7fffffffffffffffULL;
    return hash == 0 ? 1 : (int64_t)hash;
}

void memtune_xgb_v5_features_to_array(const MemTuneWorkMemFeaturesV5 *features,
    double output[MEMTUNE_XGB_V5_FEATURE_COUNT])
{
    const double values[MEMTUNE_XGB_V5_FEATURE_COUNT] = {
        features->hash_join_nodes, features->sort_nodes, features->aggregate_nodes,
        features->window_nodes, features->max_plan_rows_log10, features->max_plan_width,
        features->total_cost, features->parallel_workers_planned, features->parallel_aware_nodes,
        features->involved_table_total_size_mb, features->involved_index_total_size_mb,
        features->table_count, features->index_table_ratio, features->total_cost_log1p,
        features->table_size_log1p, features->index_size_log1p, features->rows_width_log1p,
        features->plan_node_count, features->sort_input_rows, features->sort_tuple_width,
        features->sort_input_bytes, features->sort_key_count, features->sort_input_rows_log1p,
        features->sort_input_bytes_log1p
    };
    int index;
    for (index = 0; index < MEMTUNE_XGB_V5_FEATURE_COUNT; ++index)
        output[index] = isfinite(values[index]) ? values[index] : memtune_xgb_v5_imputation[index];
}

MemTuneXgbV5Prediction memtune_predict_xgb_v5(const double input[MEMTUNE_XGB_V5_FEATURE_COUNT])
{
    MemTuneXgbV5Prediction result;
    double cache_raw = memtune_xgb_v5_predict_target(input, memtune_xgb_v5_cache_base_score,
        memtune_xgb_v5_cache_tree_offsets, memtune_xgb_v5_cache_left,
        memtune_xgb_v5_cache_right, memtune_xgb_v5_cache_split_index,
        memtune_xgb_v5_cache_split_condition, memtune_xgb_v5_cache_default_left,
        memtune_xgb_v5_cache_leaf_weight);
    double one_raw = memtune_xgb_v5_predict_target(input, memtune_xgb_v5_one_base_score,
        memtune_xgb_v5_one_tree_offsets, memtune_xgb_v5_one_left,
        memtune_xgb_v5_one_right, memtune_xgb_v5_one_split_index,
        memtune_xgb_v5_one_split_condition, memtune_xgb_v5_one_default_left,
        memtune_xgb_v5_one_leaf_weight);
    result.cache_mb = isfinite(cache_raw) ? fmax(expm1(cache_raw), MEMTUNE_XGB_V5_MIN_MB) : NAN;
    result.one_pass_mb = isfinite(one_raw) ? fmax(expm1(one_raw), MEMTUNE_XGB_V5_MIN_MB) : NAN;
    if (isfinite(result.cache_mb) && isfinite(result.one_pass_mb)) {
        result.one_pass_mb = fmin(result.one_pass_mb, result.cache_mb);
        result.multi_pass_mb = fmax(MEMTUNE_XGB_V5_MIN_MB,
            result.one_pass_mb - MEMTUNE_XGB_V5_MULTI_PASS_DELTA_MB);
    } else {
        result.multi_pass_mb = NAN;
    }
    result.model_version = MEMTUNE_XGB_V5_MODEL_VERSION;
    result.leaf_id = memtune_xgb_v5_leaf_id(result.cache_mb, result.one_pass_mb,
        result.multi_pass_mb);
    return result;
}

bool GsWorkmemXgbV5PredictDetail(const double features[MEMTUNE_XGB_V5_FEATURE_COUNT],
    GsAmmDtreeDetail *detail)
{
    MemTuneXgbV5Prediction prediction;
    double bounds[GS_AMM_DTREE_BOUND_COUNT];
    if (features == NULL || detail == NULL)
        return false;
    prediction = memtune_predict_xgb_v5(features);
    if (!isfinite(prediction.cache_mb) || !isfinite(prediction.one_pass_mb) ||
        !isfinite(prediction.multi_pass_mb) || prediction.cache_mb < prediction.one_pass_mb ||
        prediction.one_pass_mb < prediction.multi_pass_mb)
        return false;
    bounds[0] = prediction.cache_mb; bounds[1] = prediction.one_pass_mb;
    bounds[2] = prediction.multi_pass_mb;
    gs_amm_dtree_detail(bounds, prediction.model_version, prediction.leaf_id, detail);
    return true;
}
